        for k,v in data.items():
            if isinstance(v,dict): print(f'  {k}: dict[{len(v)}] keys={list(v)[:20]}')
            elif isinstance(v,list): print(f'  {k}: list[{len(v)}]')
            else: print(f'  {k}: {v"'!r}'"')
PY"

