/bin/bash -lc "python3 - <<'PY'
import json
D=json.load(open('contracts/identity/v1/fixtures/record-cases.json'))
cases=D['cases']; kind='PendingOperation'; valid=[c for c in cases if c['expect']=='valid' and c['kind']==kind]
def flat(x,p=''):
 out={}
 if isinstance(x,dict):
  for k,v in x.items(): out.update(flat(v,f'{p}.{k}' if p else k))
 elif isinstance(x,list): out[p]=x
 else: out[p]=x
 return out
for c in cases:
 if c['kind']"'!=kind: continue
 fs=flat(c['"'record']); best=min(valid,key=lambda v:sum(flat(v['record']).get(k,object())"'!=val for k,val in fs.items())+sum(k not in fs for k in flat(v['"'record'])))
 fb=flat(best['record']); keys=sorted(set(fs)|set(fb)); delta={k:{'base':fb.get(k,'<missing>'),'case':fs.get(k,'<missing>')} for k in keys if fb.get(k,object())"'!=fs.get(k,object())}
 extras={k:v for k,v in c.items() if k not in {'"'id','kind','expect','violations','record'}}
 print(f\"{c['id']} [{c['expect']}] violations={c['violations']} closest={best['id']}\")
 if delta: print('  delta='+json.dumps(delta,sort_keys=True,separators=(',',':')))
 if extras: print('  context='+json.dumps(extras,sort_keys=True,separators=(',',':')))
PY"

