   633	/**
   634	 * Resolve one semantic action on a route to its catalog row. The action is what the handler is
   635	 * about to perform; it is not a client-supplied risk label. An action the catalog does not list is
   636	 * Px, and so is an action under a prefix the route refuses outright.
   637	 */
   638	export function dispatchAction(manifest: LoadedManifest, route: string, action: string): Classification {
   639	  const entry = manifest.dispatch.get(route);
   640	  if (entry === undefined) return { id: `${route}#${action}`, class: "PX", refusal: "no_dispatch_route", route };
   641	  if ((entry.refused_prefixes ?? []).some((prefix) => action.startsWith(prefix))) {
   642	    return { id: `${route}#${action}`, class: "PX", refusal: "reserved_for_person", route };
   643	  }
   644	  const operationId = entry.actions[action];
   645	  if (operationId === undefined) return { id: `${route}#${action}`, class: "PX", refusal: "unknown_action", route };
   646	  return classify(manifest, operationId);
   647	}
