   662	/**
   663	 * Resolve the operation a dispatched route performs.
   664	 *
   665	 * The route names an action, and the handler resolves the qualifier the catalog asks for: the
   666	 * desk resolves the kind of the card it fetched, the phone resolves the settlement phase it
   667	 * accepted. A pair the catalog lists selects that pair's operation. An action with no pair
   668	 * selects the action's own row. An action that is in neither is Px: the route refuses it before
   669	 * the effect runs, and a route never picks a weaker row for the same action.
   670	 */
   671	export function resolveDispatchedOperation(
   672	  manifest: LoadedManifest,
   673	  route: string,
   674	  action: string,
   675	  resolved?: string | null,
   676	): string | null {
   677	  const entry = manifest.dispatch.get(route);
   678	  if (entry === undefined) return null;
   679	  for (const combination of entry.combinations ?? []) {
   680	    if (combination.action !== action) continue;
   681	    if (combination.resolved === "*") return combination.operation;
   682	    if (resolved !== undefined && resolved !== null && combination.resolved === resolved) return combination.operation;
   683	  }
   684	  return entry.actions[action] ?? null;
   685	}
