   740	    // its expiry. The plain intent path has no pending record, no confirmation and no authority
   741	    // writer, so it cannot honour any of those. The reference is refused here, before a capability
   742	    // is invoked and before a record is appended, and it reaches its own path instead.
   743	    return { operationRef, class: "deployment", allowed: false, reason: "deployment_bound_operation_needs_its_own_path" };
   744	  }
   745	  return { operationRef, class: "PX", allowed: false, reason: "unclassified_operation" };
   746	}
