 711	/**
 712	 * Classify an operation reference before anything runs.
 713	 *
 714	 * The catalog classifies Horizon's own operations. A reference the catalog does not know may still
 715	 * be a deployment-bound operation, whose authority is its own binding contract and never this
 716	 * catalog's. A reference that is neither is Px: it is refused before a capability is invoked and
 717	 * before a record is appended.
 718	 *
 719	 * A governed row (P2 or P3) is not allowed on the local intent path. Its effect needs the pending
 720	 * record, the confirmation and the authority writer its own row names, and a plain intent commit
 721	 * carries none of them.
 722	 */
 723	export function classifyReference(
 724	  manifest: LoadedManifest,
 725	  operationRef: string,
 726	  deploymentBound: ReadonlySet<string>,
 727	): ReferenceClassification {
 728	  const operation = manifest.byId.get(operationRef);
 729	  if (operation !== undefined) {
 730	    if (operation.class === "P0" || operation.class === "P1") {
 731	      return { operationRef, class: operation.class, allowed: true, reason: "catalogued_local_operation" };
 732	    }
 733	    if (operation.class === "P2" || operation.class === "P3") {
 734	      return { operationRef, class: operation.class, allowed: false, reason: "governed_operation_needs_confirmation" };
 735	    }
 736	    return { operationRef, class: "PX", allowed: false, reason: "px_operation" };
 737	  }
 738	  if (deploymentBound.has(operationRef)) {
 739	    // A deployment-bound operation keeps its own binding contract: its authority, its evidence and
 740	    // its expiry. The plain intent path has no pending record, no confirmation and no authority
 741	    // writer, so it cannot honour any of those. The reference is refused here, before a capability
 742	    // is invoked and before a record is appended, and it reaches its own path instead.
 743	    return { operationRef, class: "deployment", allowed: false, reason: "deployment_bound_operation_needs_its_own_path" };
 744	  }
 745	  return { operationRef, class: "PX", allowed: false, reason: "unclassified_operation" };
 746	}
