190	function fieldViolations(fields: readonly ParamFieldSpec[], parameters: Record<string, unknown>): string[] {
191	  const out: string[] = [];
192	  const declared = new Map<string, ParamFieldSpec>();
193	  for (const field of fields) declared.set(wireName(field), field);
194	  for (const field of fields) {
195	    const name = wireName(field);
196	    if (!(name in parameters)) {
197	      if (field.optional !== true) out.push(`params:missing:${name}`);
198	      continue;
199	    }
200	    checkField(field, parameters[name], name, out);
201	  }
202	  for (const name of Object.keys(parameters)) {
203	    if (!declared.has(name)) out.push(`params:unknown:${name}`);
204	  }
205	  return out;
206	}
