208	/**
209	 * Check one value against one field's declaration, recursively.
210	 *
211	 * A nested object's members are checked against their own declarations, so a nested field's
212	 * optionality and nullability are facts rather than assumptions, and an array's elements are
213	 * checked against the element declaration. The path names where the violation is: `surface.title`,
214	 * `ask.options[0].option_id`.
215	 */
216	function checkField(field: ParamFieldSpec, value: unknown, path: string, out: string[]): void {
217	  if (value === null) {
218	    if (field.nullable !== true) out.push(`params:null:${path}`);
219	    return;
220	  }
221	  if (!typeHolds(field.type, value)) {
222	    out.push(`params:type:${path}:${field.type}`);
223	    return;
224	  }
225	  if (field.enum !== undefined && !field.enum.some((allowed) => allowed === value)) {
226	    out.push(`params:enum:${path}`);
227	  }
228	  if (field.object_fields !== undefined && isPlainObject(value)) {
229	    for (const nested of field.object_fields) {
230	      const key = wireName(nested);
231	      const nestedPath = `${path}.${key}`;
232	      if (!(key in value)) {
233	        if (nested.optional !== true) out.push(`params:missing:${nestedPath}`);
234	        continue;
235	      }
236	      checkField(nested, value[key], nestedPath, out);
237	    }
238	  }
239	  if (field.items !== undefined && Array.isArray(value)) {
240	    value.forEach((entry, index) => checkItem(field.items!, entry, `${path}[${index}]`, out));
241	  }
242	}
