244	/** Check one array element against the element declaration. */
245	function checkItem(item: ParamItemSpec, value: unknown, path: string, out: string[]): void {
246	  if (value === null) {
247	    if (item.nullable !== true) out.push(`params:null:${path}`);
248	    return;
249	  }
250	  if (!typeHolds(item.type, value)) {
251	    out.push(`params:type:${path}:${item.type}`);
252	    return;
253	  }
254	  if (item.enum !== undefined && !item.enum.some((allowed) => allowed === value)) {
255	    out.push(`params:enum:${path}`);
256	  }
257	  if (item.object_fields !== undefined && isPlainObject(value)) {
258	    for (const nested of item.object_fields) {
259	      const key = wireName(nested);
260	      const nestedPath = `${path}.${key}`;
261	      if (!(key in value)) {
262	        if (nested.optional !== true) out.push(`params:missing:${nestedPath}`);
263	        continue;
264	      }
265	      checkField(nested, value[key], nestedPath, out);
266	    }
267	  }
268	  if (item.items !== undefined && Array.isArray(value)) {
269	    value.forEach((entry, index) => checkItem(item.items!, entry, `${path}[${index}]`, out));
270	  }
271	}
