286	export function fieldsFor(
287	  schema: ParamSchemaSpec,
288	  record: Record<string, unknown> = {},
289	): { readonly fields: readonly ParamFieldSpec[]; readonly variant: string | null; readonly resolved: boolean } {
290	  if (schema.variants === undefined) return { fields: schema.fields ?? [], variant: null, resolved: true };
291	  const key = schema.discriminator ?? schema.discriminated_by;
292	  if (key !== undefined) {
